#include <stdio.h>

void hanoi(int disks, char from, char via, char to) {
    if (disks == 0) {
        return;
    }
    hanoi(disks - 1, from, to, via);
    printf("%c->%c\n", from, to);
    hanoi(disks - 1, via, from, to);
}

int main() {
    hanoi(3, 'A', 'B', 'C');
    return 0;
}
